using System;using System.IO;using System.Linq;using System.Drawing;using System.Globalization;using System.Collections.Generic;using System.Windows.Forms;
namespace CircuitoStudio {
public sealed class MotorStarterSelectionForm:Form {
Project project;Circuit circuit;string file;List<MotorStarterRating> rows,visible;ComboBox kind,poles,supply;TextBox motorA,motorSource,service,tripClass,coordination,control,details;ListBox list;public bool Changed{get;private set;}
public MotorStarterSelectionForm(Project p,Circuit c,string library){project=p;circuit=c;file=library;rows=File.Exists(file)?MotorStarterSelection.Import(file):new List<MotorStarterRating>();Text="Contator, partida manual e relé térmico";Size=new Size(1230,840);MinimumSize=new Size(1140,750);Font=new Font("Segoe UI",10);StartPosition=FormStartPosition.CenterParent;var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=215,Padding=new Padding(8)};Add(top,"Importar CSV",Import);Add(top,"Modelo vazio",EmptyTemplate);Add(top,"Modelo da proteção atual",CurrentTemplate);Add(top,"Selecionar conjunto",Apply);Add(top,"Remover seleção",Remove);top.SetFlowBreak(top.Controls[top.Controls.Count-1],true);kind=Picker(top,"Conjunto",new[]{"Contator + térmico","Manobra manual + térmico","Disjuntor-motor manual"},230);poles=Picker(top,"Polos",Enum.GetValues(typeof(PoleLayout)).Cast<PoleLayout>().Select(x=>BreakerSelection.PoleName(x)).ToArray(),80);motorA=Field(top,"Corrente de placa (A)",100);top.SetFlowBreak(motorA,true);motorSource=Field(top,"Referência da placa",750);top.SetFlowBreak(motorSource,true);service=Field(top,"Serviço exigido",120);tripClass=Field(top,"Classe exigida",100);coordination=Field(top,"Coordenação exigida",150);top.SetFlowBreak(coordination,true);control=Field(top,"Comando (V)",90);supply=Picker(top,"Bobina",new[]{"Não se aplica / desconhecida","AC","DC"},220);Add(top,"Atualizar comparação",RefreshDetails);var note=new Label{Dock=DockStyle.Top,Height=70,Padding=new Padding(10),Text=c.Id+"; "+c.Voltage+" V; "+p.Frequency+" Hz; corrente nominal calculada sem demanda="+MotorStarterSelection.NominalCurrent(c).ToString("G8",CultureInfo.CurrentCulture)+" A.\r\nSelecionar pelo motor nominal, serviço/classe e documento do conjunto. Ajuste1:1 somente para térmico em linha; sem conversão automática para triângulo, coordenação ou suportabilidade à partida presumidas."};list=new ListBox{Dock=DockStyle.Top,Height=125,HorizontalScrollbar=true};details=new TextBox{Dock=DockStyle.Fill,ReadOnly=true,Multiline=true,ScrollBars=ScrollBars.Vertical,BackColor=Color.White};Controls.Add(details);Controls.Add(list);Controls.Add(note);Controls.Add(top);var selected=c.MotorStarterSelection;kind.SelectedIndex=selected==null?0:(int)selected.Rating.Kind;poles.SelectedIndex=selected==null?(c.Phases==PhaseMode.Trifasico?(int)PoleLayout.ThreePole:(int)PoleLayout.OnePoleNeutral):(int)selected.RequiredPoles;motorA.Text=selected==null||selected.MotorRatedA==0?"":selected.MotorRatedA.ToString(CultureInfo.CurrentCulture);motorSource.Text=selected==null?"":selected.MotorNameplateSource;service.Text=selected==null?"":selected.RequiredService;tripClass.Text=selected==null?"":selected.RequiredTripClass;coordination.Text=selected==null?"":selected.RequiredCoordinationType;control.Text=selected==null||selected.ControlVoltageV==0?"":selected.ControlVoltageV.ToString(CultureInfo.CurrentCulture);supply.SelectedIndex=selected==null?0:(int)selected.ControlSupply;kind.SelectedIndexChanged+=delegate{if(kind.SelectedIndex!=0){control.Text="";supply.SelectedIndex=0;}RefreshRows();};poles.SelectedIndexChanged+=delegate{RefreshDetails();};supply.SelectedIndexChanged+=delegate{RefreshDetails();};list.SelectedIndexChanged+=delegate{RefreshDetails();};Shown+=delegate{details.SelectionStart=0;details.SelectionLength=0;details.ScrollToCaret();list.Focus();};RefreshRows();}
static ComboBox Picker(FlowLayoutPanel panel,string label,string[] items,int width){panel.Controls.Add(new Label{Text=label,AutoSize=true,Margin=new Padding(5,8,3,0)});var box=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=width};box.Items.AddRange(items.Cast<object>().ToArray());panel.Controls.Add(box);return box;}
static TextBox Field(FlowLayoutPanel panel,string label,int width){panel.Controls.Add(new Label{Text=label,AutoSize=true,Margin=new Padding(5,8,3,0)});var box=new TextBox{Width=width,MaxLength=2000};panel.Controls.Add(box);return box;}
void Add(FlowLayoutPanel panel,string label,Action action){var button=new Button{Text=label,AutoSize=true};button.Click+=delegate{try{action();}catch(Exception ex){MessageBox.Show(this,ex.Message,"Partida",MessageBoxButtons.OK,MessageBoxIcon.Warning);}};panel.Controls.Add(button);}
static double Number(string text){if(String.IsNullOrWhiteSpace(text))return 0;double value;if(text.Contains('.')&&text.Contains(',')||!Double.TryParse(text.Replace(',','.'),NumberStyles.Float,CultureInfo.InvariantCulture,out value)||Double.IsNaN(value)||Double.IsInfinity(value))throw new InvalidDataException("Informe número finito sem separador de milhares.");return value;}
MotorStarterBinding Candidate(MotorStarterRating rating){return new MotorStarterBinding{Engine=MotorStarterSelection.EngineId,Rating=rating,MotorRatedA=Number(motorA.Text),MotorNameplateSource=motorSource.Text,RequiredService=service.Text,RequiredTripClass=tripClass.Text,RequiredCoordinationType=coordination.Text,RequiredPoles=(PoleLayout)poles.SelectedIndex,ControlVoltageV=Number(control.Text),ControlSupply=(ControlSupply)supply.SelectedIndex};}
void RefreshRows(){visible=rows.Where(x=>x.Kind==(MotorStarterKind)kind.SelectedIndex).ToList();list.Items.Clear();foreach(var r in visible)list.Items.Add(r.Manufacturer+" / "+r.Reference+"; controlador "+r.ControllerReference+"; térmico "+r.OverloadReference+"; "+r.RatedMotorA+" A; "+r.Service+"; classe "+r.TripClass+"; "+r.CoordinationType);if(list.Items.Count>0)list.SelectedIndex=0;else RefreshDetails();}
void RefreshDetails(){var study=Engineering.Analyze(project);var saved=MotorStarterSelection.Evaluate(project,study,circuit,circuit.MotorStarterSelection);details.Text="SELEÇÃO SALVA\r\n"+saved.Status+"\r\n"+saved.Detail;if(list.SelectedIndex>=0){try{var result=MotorStarterSelection.Evaluate(project,study,circuit,Candidate(visible[list.SelectedIndex]));details.AppendText("\r\n\r\nCANDIDATO\r\n"+result.Status+"\r\n"+result.Detail);}catch(InvalidDataException ex){details.AppendText("\r\n\r\nREQUISITOS INCOMPLETOS/INVÁLIDOS: "+ex.Message);}}details.SelectionStart=0;details.SelectionLength=0;}
void Import(){using(var d=new OpenFileDialog{Filter="CSV|*.csv"})if(d.ShowDialog(this)==DialogResult.OK){var imported=MotorStarterSelection.Import(d.FileName);MotorStarterSelection.Export(imported,file);rows=imported;RefreshRows();}}
void EmptyTemplate(){SaveTemplate(false);}void CurrentTemplate(){SaveTemplate(true);}void SaveTemplate(bool current){using(var d=new SaveFileDialog{Filter="CSV|*.csv",FileName=current?"modelo-partida-protecao-atual.csv":"modelo-partidas.csv"})if(d.ShowDialog(this)==DialogResult.OK){if(String.Equals(Path.GetFullPath(d.FileName),Path.GetFullPath(file),StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Use outro nome para preservar a biblioteca.");MotorStarterSelection.Export(current?new[]{MotorStarterSelection.Template(project,circuit,(MotorStarterKind)kind.SelectedIndex)}:new MotorStarterRating[0],d.FileName);}}
void Apply(){if(list.SelectedIndex<0)return;MotorStarterSelection.Apply(project,circuit,Candidate(visible[list.SelectedIndex]));Changed=true;DialogResult=DialogResult.OK;Close();}
void Remove(){circuit.MotorStarterSelection=null;Changed=true;DialogResult=DialogResult.OK;Close();}
}
partial class Studio{void ConfigureMotorStarterSelection(){if(circuit==null)throw new InvalidOperationException("Selecione um circuito terminal de motor.");using(var form=new MotorStarterSelectionForm(project,circuit,Path.Combine(userData,"conjuntos-partida.csv")))if(form.ShowDialog(this)==DialogResult.OK&&form.Changed){Change();tabs.SelectedTab=studyPage;}}}
}
